def item1(n1,d1,base,pw,dec,n2,d2):
    v1=F(n1,d1);v2=F(base)**pw;v3=F(str(dec));v4=F(n2,d2)
    r1=v1*v2;r2=r1*v3;r3=r2*v4
    assert r3.denominator==1
    sup={2:'²',3:'³',4:'⁴'}[pw]
    q=f"จงหาผลลัพธ์ของ<div class='math'>{fr(n1,d1)} × {base}<sup>{pw}</sup> × {dec} × {fr(n2,d2)}</div>"
    st=[f"{base}{sup} = {int(v2)} → {fr(n1,d1)} × {int(v2)} = {g(r1)}",f"{g(r1)} × {dec} = {g(r2)}",f"{fr(n2,d2)} = {g(v4)} → {g(r2)} × {g(v4)} = {int(r3)}"]
    return I(q,st,int(r3),f"ตรวจ: คิดอีกทาง {g(v2)} × {g(v3)} = {g(v2*v3)} แล้วคูณ {fr(n1,d1)} × {fr(n2,d2)} = {g(v1*v4)} → {g(v2*v3)} × {g(v1*v4)} = {int(r3)} ✓")
