def item10(letters,digits,cond_txt,cond):
    L=len(letters);D=len(digits)
    ok=[p for p in itertools.permutations(digits) if cond(int(''.join(map(str,p))))]
    lw=math.factorial(L);tot=2*lw*len(ok)
    sym=', '.join(letters+[str(d) for d in digits])
    q=f"หากนำสัญลักษณ์ {sym} ทุกตัวมาเรียงกัน โดยห้ามใช้ซ้ำ และตัวอักษร {L} ตัวต้องอยู่ติดกัน ตัวเลข {D} ตัวต้องอยู่ติดกัน แต่สลับกลุ่มตัวเลขหรือกลุ่มตัวอักษรขึ้นก่อนได้ ถ้าต้องการให้ตัวเลขที่เรียงได้{cond_txt} จะจัดเรียงได้ทั้งหมดกี่วิธี"
    ex=', '.join(''.join(map(str,p)) for p in ok[:6])+(' …' if len(ok)>6 else '')
    st=[f"สลับกลุ่มได้ 2 แบบ (กลุ่มตัวอักษรก่อน หรือกลุ่มตัวเลขก่อน)",f"เรียงตัวอักษร {L} ตัว = {' × '.join(str(i) for i in range(L,0,-1))} = {lw} วิธี",f"เรียงตัวเลขให้{cond_txt} ได้ {len(ok)} วิธี เช่น {ex}",f"ทั้งหมด = 2 × {lw} × {len(ok)} = {tot} วิธี"]
    return I(q,st,tot,f"ตรวจ: ตัวเลขที่เรียงได้ทั้งหมด {math.factorial(D)} แบบ เข้าเงื่อนไข {len(ok)} แบบ ✓",note="ตีความว่า \"ตัวเลขที่เรียงได้\" คือเลขที่เกิดจากตัวเลขกลุ่มนั้นอ่านต่อกัน")
