def mk13(q,pr,each,k,pay,names):
    u=[F(p,c) for p,c in pr];cnt=[e*k for e in each];cost=[a*b for a,b in zip(u,cnt)];tot=sum(cost);ch=pay-tot
    assert all(x.denominator==1 for x in u+cost) and ch>=0,(u,cost)
    st=["ราคาต่อชิ้น: "+', '.join(f"{names[i]} {pr[i][0]} ÷ {pr[i][1]} = {int(u[i])}" for i in range(3))+" บาท"]
    st.append("จำนวนที่ซื้อ: "+', '.join(f"{names[i]} {each[i]} × {k} = {cnt[i]}" for i in range(3))+" ชิ้น")
    st.append("ค่าของ = "+' + '.join(f"{cnt[i]} × {int(u[i])}" for i in range(3))+f" = {' + '.join(str(int(c)) for c in cost)} = {int(tot)} บาท")
    st.append(f"เงินทอน = {fm(pay)} − {int(tot)} = {int(ch)} บาท")
    return q,st,int(ch),f"ตรวจ: {int(tot)} + {int(ch)} = {fm(pay)} ✓"
