    return I(q,[f"{n2} = {a:.2f} + {d1:.2f} = {b:.2f} {unit}",f"{n3} = {b:.2f} − {d2:.2f} = {c:.2f} {unit}",f"รวม = {a:.2f} + {b:.2f} + {c:.2f} = {s:.2f} {unit}",f"ร้อยละ = {s:.2f} ÷ {total} × 100 = {int(round(pct))}"],int(round(pct)),f"ตรวจ: {int(round(pct))}% ของ {total} = {total} × {int(round(pct))} ÷ 100 = {s:.2f} ✓")
