    return I(q,[f"นักเรียนชาย = {n} × {frac_n} ÷ {frac_d} = {boys} คน → นักเรียนหญิง = {n} − {boys} = {girls} คน",f"เสื้อ {n} ตัว = {n} × {g(s)} = {g(A)} เมตร",f"กางเกง {boys} ตัว = {boys} × {g(p)} = {g(B)} เมตร  ·  กระโปรง {girls} ตัว = {girls} × {g(k)} = {g(C)} เมตร",f"ผ้าทั้งหมด = {g(A)} + {g(B)} + {g(C)} = {g(tot)} เมตร"],g(tot).replace(',',''),f"ตรวจ: ชุดละ 1 เสื้อ + 1 ท่อนล่าง รวม {n} ชุด ✓")
