# ---------------- 27 ----------------
def item27(a,shade):
    radii=[4*a//4*i for i in (4,3,2,1)] if False else [a*4//1*0+a*k for k in (4,3,2,1)]
    r=[ (a//2)*k for k in (4,3,2,1)] if False else None
    # smallest circle diameter = a -> radius a/2
    rr=[F(a,2)*k for k in (4,3,2,1)]
    paint=shade
    fills=['#8393AD' if s else '#fff' for s in paint]
    fig=fg.circles([float(x) for x in rr],fills)
    # area/pi: shaded = sum over shaded layers
    # layers: ring i = circle_i - circle_{i+1} etc.  paint[i] colour of circle i drawn on top of previous
    area=F(0);prev=F(0)
    # compute painted area by sequential painting: area_of_colour = sum_i (r_i^2 - r_{i+1}^2)*[colour_i shaded]
    sq=[x*x for x in rr]+[F(0)]
    for i in range(4):
        if paint[i]: area+=sq[i]-sq[i+1]
    A=area
    items=[]
    terms=[(i,sq[i],sq[i+1]) for i in range(4) if paint[i]]
    st=[f"a = เส้นผ่านศูนย์กลางวงกลมเล็กสุด = {a} ซม.",f"เส้นผ่านศูนย์กลางทั้ง 4 วง = {', '.join(str(int(x*2)) for x in reversed(rr))} ซม. → รัศมี = {', '.join(g(x) for x in reversed(rr))} ซม.",f"พื้นที่แรเงา = "+' + '.join(f"π({g(sq[i])} − {g(sq[i+1])})" if sq[i+1]!=0 else f"π × {g(sq[i])}" for i,_,_ in terms),f"A ÷ π = "+' + '.join(f"({g(sq[i])} − {g(sq[i+1])})" if sq[i+1]!=0 else f"{g(sq[i])}" for i,_,_ in terms)+f" = {g(A)}"]
    return I(f"ส่วนที่แรเงาทั้งหมดมีพื้นที่ A ตารางเซนติเมตร ระยะ a ระหว่างเส้นรอบวงแต่ละเส้นเท่ากัน และเท่ากับเส้นผ่านศูนย์กลางของวงกลมที่เล็กที่สุดซึ่งยาว {a} เซนติเมตร จงหา A ÷ π (π = {fr(22,7)})",st,g(A),f"ตรวจ: A = {g(A)} × {fr(22,7)} ซม.² ตัวเลขไม่ต้องใช้ {fr(22,7)} เพราะหารด้วย π แล้วตัดกัน ✓",qimg=fig,aimg=fig,note="รัศมี = เส้นผ่านศูนย์กลาง ÷ 2")
add(27,"พื้นที่วงกลมซ้อนกัน","พื้นที่วงแหวน = π(R² − r²) ทุกวงมี π ร่วมกัน","รัศมี = เส้นผ่านศูนย์กลาง ÷ 2 อย่าใช้เส้นผ่านศูนย์กลางแทนรัศมี",item27(4,[1,0,1,0]),item27(6,[1,0,1,0]),item27(4,[1,0,0,1]))
