def ang(h,m):
    ha=(h%12)*30+m*0.5;ma=m*6;d=abs(ha-ma)%360;return ha,ma,min(d,360-d)
def item28(t1,t2,thing="นาฬิกา"):
    r=[ang(*t1),ang(*t2)];tot=r[0][2]+r[1][2]
    fig,a1,a2=fg.clocks(t1,t2)
    def part(t,rr):
        h,m=t;d=abs(rr[0]-rr[1])
        extra=f" → ใช้มุมที่เล็กกว่า 360 − {g(d)} = {g(rr[2])}°" if d>180 else ""
        return [f"{h:02d}.{m:02d} น.: เข็มสั้น {h%12}×30 + {m}×0.5 = {g(rr[0])}°, เข็มยาว {m}×6 = {rr[1]}° → ต่างกัน {g(d)}°{extra}"]
    st=part(t1,r[0])+part(t2,r[1])+[f"มุมรวม = {g(r[0][2])} + {g(r[1][2])} = {g(tot)}°"]
    return I(f"{thing}สองเรือนแขวนอยู่บนผนังและแสดงเวลาต่างกัน เรือนที่หนึ่งแสดงเวลา {t1[0]:02d}.{t1[1]:02d} น. และเรือนที่สองแสดงเวลา {t2[0]:02d}.{t2[1]:02d} น. เข็มสั้นและเข็มยาวของนาฬิกาทั้งสองเรือนทำมุมรวมกันได้ทั้งหมดกี่องศา",st,g(tot),f"ตรวจ: เรือนที่ 1 = {g(r[0][2])}° เรือนที่ 2 = {g(r[1][2])}° (แต่ละเรือนไม่เกิน 180°) ✓",aimg=fig,note="ตีความว่าให้ใช้มุมที่เล็กกว่า 180° ในแต่ละนาฬิกา")
