# ---------------- 29 ----------------
def item29(w,h,sides,desc):
    area_rect=w*h
    semi=[]
    for s in sides:
        d=w if s in 'TB' else h;semi.append(F(d,2)**2/2)  # times pi
    pi_part=sum(semi)  # coefficient of pi
    val=pi_part*F(22,7);tot=area_rect+val;assert tot.denominator==1,(tot,)
    fig=fg.garden(w,h,sides)
    st=[f"บ่อน้ำเป็นสี่เหลี่ยม {w} × {h} → พื้นที่ = {w*h} ตารางหน่วย",f"ครึ่งวงกลมแต่ละด้านมีเส้นผ่านศูนย์กลางเท่ากับความยาวด้านที่ติดกัน"]
    if len(sides)==4:
        st.append(f"ครึ่งวงกลม 4 ด้านรวมเป็นวงกลมเต็ม {2*(1 if w==h else 1)} วง" if w==h else f"ครึ่งวงกลมด้านยาว 2 ด้านรวมเป็นวงกลมรัศมี {g(F(w,2))} และด้านกว้าง 2 ด้านรวมเป็นวงกลมรัศมี {g(F(h,2))}")
    areas=[f"π × {g(F(w if s in 'TB' else h,2))}² ÷ 2" for s in sides]
    st.append(f"พื้นที่ครึ่งวงกลมรวม = π × ("+' + '.join(g((F(w if s in 'TB' else h,2))**2/2) for s in sides)+f") = {fr(22,7)} × {g(pi_part)} = {g(val)}")
    st.append(f"พื้นที่ทั้งหมด = {w*h} + {g(val)} = {g(tot)} ตารางหน่วย")
    return I(desc,st,g(tot),f"ตรวจ: {w*h} + {g(val)} = {g(tot)} ✓",qimg=fig,aimg=fig)
